  <Field label="Licencia del jefe · simulación"><select value={assistantPlan(s)} onChange={e=>act(state=>changeAssistantPlan(state,e.target.value as keyof typeof assistantPlans,actor),'Plan de demostración actualizado.')}><option value="basic">Básica · 1 asistente</option><option value="intermediate">Intermedia · 3 asistentes</option><option value="unlimited">Superior · asistentes ilimitados</option></select></Field>
